CREATE TABLE IF NOT EXISTS ua_facilities ( id INTEGER PRIMARY KEY, name TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, cap_3h INTEGER NOT NULL DEFAULT 0, cap_7h INTEGER NOT NULL DEFAULT 0, use_am INTEGER NOT NULL DEFAULT 1, use_pm INTEGER NOT NULL DEFAULT 1, use_7h INTEGER NOT NULL DEFAULT 1 );
CREATE TABLE IF NOT EXISTS ua_daily_records ( facility_id INTEGER NOT NULL REFERENCES ua_facilities(id), date TEXT NOT NULL, am_support INTEGER, am_care INTEGER, pm_support INTEGER, pm_care INTEGER, full_care INTEGER, updated_at TEXT NOT NULL, updated_by INTEGER, PRIMARY KEY (facility_id, date) );
CREATE INDEX IF NOT EXISTS idx_ua_daily_records_date ON ua_daily_records(date);
